#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Google Cloud and AWS setup for The Lobby's Add to Google Calendar
# (the-lobby #52). Run on Craig's Mac. It writes the Google client's ID and
# secret and a new token key as SecureStrings under /the-lobby/<env>/google/,
# and remembers only the two Google project IDs between runs.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9
ENV_FILE="$HOME/.the-lobby-google-wizard.env"
PROFILE=workloads-admin
REGION=us-west-2
DEV_CALLBACK="https://dev.craigdevjohnson.com/soccer/google/callback"
NEXT_CALLBACK="https://next.craigdevjohnson.com/soccer/google/callback"
APEX_CALLBACK="https://craigdevjohnson.com/soccer/google/callback"
NOTES=()

# put_param NAME VALUE writes one SecureString with the account's aws/ssm key.
put_param() {
  aws ssm put-parameter --profile "$PROFILE" --region "$REGION" \
    --name "$1" --type SecureString --overwrite --value "$2" >/dev/null
  printf '  %s✓ saved%s %s\n' "$GREEN" "$RESET" "$1"
}

# save_settings ENV CLIENT_ID CLIENT_SECRET writes the three SecureStrings.
# A token key already there is kept: a new one would make every Member who
# connected on that site connect again.
save_settings() {
  local env="$1" id="$2" secret="$3" path="/the-lobby/$1/google/"
  if [[ -z "$id" || -z "$secret" ]]; then
    warn "The client ID or secret is empty, so nothing was saved for $env. Re-run the wizard."
    SKIPPED+=("$env settings in Parameter Store")
    pause
    return
  fi
  say "This writes three SecureStrings in AWS (account 793680745829, $REGION):"
  note "  ${path}client-id, ${path}client-secret, ${path}token-key"
  if ! confirm "Write them now?"; then
    SKIPPED+=("$env settings in Parameter Store")
    return
  fi
  put_param "${path}client-id" "$id"
  put_param "${path}client-secret" "$secret"
  if aws ssm get-parameter --profile "$PROFILE" --region "$REGION" --name "${path}token-key" >/dev/null 2>&1; then
    note "  ${path}token-key is already there; kept it."
  else
    put_param "${path}token-key" "$(openssl rand -base64 32)"
  fi
  pause
}

banner "Add to Google Calendar: Google Cloud and AWS setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools and your AWS sign-in"
for tool in aws openssl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    warn "$tool isn't installed. Install it (brew install awscli openssl), then run this again."
    exit 1
  fi
done
if ! aws sts get-caller-identity --profile "$PROFILE" >/dev/null 2>&1; then
  say "Signing you in to AWS as $PROFILE. A browser page opens; approve it."
  aws sso login --profile "$PROFILE"
fi
account=$(aws sts get-caller-identity --profile "$PROFILE" --query Account --output text)
if [[ "$account" != "793680745829" ]]; then
  warn "$PROFILE is signed in to account $account, not 793680745829. Stopping."
  exit 1
fi
say "${GREEN}✓${RESET} Signed in to AWS account 793680745829 as $PROFILE."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Dev Google project: add The Lobby's dev address to the client"
say "Use the dev Google project the old site used."
open_url "https://console.cloud.google.com/auth/clients"
step "Switch to the dev project with the project picker at the top. Its ID shows there (it looks like name-123456)."
ask DEV_PROJECT "Paste the dev project's ID:"
write_env DEV_PROJECT "$DEV_PROJECT"
open_url "https://console.cloud.google.com/auth/clients?project=$DEV_PROJECT"
step "Click the Web application client the old dev site signs in with."
step "Under Authorized redirect URIs, click Add URI and paste:"
note "    $DEV_CALLBACK"
step "Click Save at the bottom."
step "Copy the Client ID (it ends in .apps.googleusercontent.com)."
ask DEV_CLIENT_ID "Paste the dev Client ID:"
write_env DEV_CLIENT_ID "$DEV_CLIENT_ID"
step "Under Client secrets, click Add secret, then copy the new secret. Google shows it only once."
note "Leave the old secret enabled: the old site still uses it."
ask_secret DEV_CLIENT_SECRET "Paste the new dev client secret (hidden):"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Dev Google project: permissions and the Calendar API"
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com?project=$DEV_PROJECT"
step "If the page says API Enabled, you're done here. If it shows an Enable button, click it. The calendar scopes below only appear once it is enabled."
pause "Press Enter when the Google Calendar API is enabled."
open_url "https://console.cloud.google.com/auth/scopes?project=$DEV_PROJECT"
step "Check these four scopes are listed. Any that are missing: click Add or remove scopes, tick it (or paste it under Manually add scopes), Update, then Save."
note "    openid"
note "    https://www.googleapis.com/auth/userinfo.email"
note "    https://www.googleapis.com/auth/calendar.events"
note "    https://www.googleapis.com/auth/calendar.calendarlist.readonly"
pause "Press Enter when all four are there."
open_url "https://console.cloud.google.com/auth/audience?project=$DEV_PROJECT"
step "Testing is fine for dev, as long as your own Google account is under Test users. Add it if it isn't."
note "In Testing, dev's calendar access lasts seven days at a time; Connect again after that."
pause "Press Enter when your account can use the dev project."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Dev: save the settings in AWS"
save_settings dev "$DEV_CLIENT_ID" "$DEV_CLIENT_SECRET"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Production Google project: add The Lobby's addresses to the client"
say "Use the production Google project the old site used."
open_url "https://console.cloud.google.com/auth/clients"
step "Switch to the production project with the project picker at the top, and copy its ID from there."
ask PROD_PROJECT "Paste the production project's ID:"
write_env PROD_PROJECT "$PROD_PROJECT"
open_url "https://console.cloud.google.com/auth/clients?project=$PROD_PROJECT"
step "Click the Web application client the old site signs in with."
step "Under Authorized redirect URIs, click Add URI for each of these (skip one that's already there):"
note "    $NEXT_CALLBACK"
note "    $APEX_CALLBACK"
step "Click Save at the bottom."
step "Copy the Client ID (it ends in .apps.googleusercontent.com)."
ask PROD_CLIENT_ID "Paste the production Client ID:"
write_env PROD_CLIENT_ID "$PROD_CLIENT_ID"
step "Under Client secrets, click Add secret, then copy the new secret. Google shows it only once."
note "Leave the old secret enabled: craigdevjohnson.com still runs the old site."
ask_secret PROD_CLIENT_SECRET "Paste the new production client secret (hidden):"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Production Google project: permissions and the Calendar API"
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com?project=$PROD_PROJECT"
step "If it shows an Enable button, click it. The calendar scopes below only appear once it is enabled."
pause "Press Enter when the Google Calendar API is enabled."
open_url "https://console.cloud.google.com/auth/scopes?project=$PROD_PROJECT"
step "Check the same four scopes are listed, adding any that are missing (tick them, or paste under Manually add scopes), then Save:"
note "    openid"
note "    https://www.googleapis.com/auth/userinfo.email"
note "    https://www.googleapis.com/auth/calendar.events"
note "    https://www.googleapis.com/auth/calendar.calendarlist.readonly"
step "Look at which group .../auth/calendar.events sits in: Non-sensitive, Sensitive or Restricted."
ask EVENTS_CLASS "Type the group it's in:"
NOTES+=("calendar.events is classed as: $EVENTS_CLASS")

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Production Google project: publishing status and user cap"
open_url "https://console.cloud.google.com/auth/branding?project=$PROD_PROJECT"
step "Google refuses to publish until Branding is complete. Fill any of these that are empty, then Save:"
note "    App name, User support email, Developer contact email"
note "    Authorized domains: craigdevjohnson.com"
note "    Application home page: https://craigdevjohnson.com"
note "    Application privacy policy link: https://next.craigdevjohnson.com/privacy"
pause "Press Enter when Branding is saved."
open_url "https://console.cloud.google.com/auth/audience?project=$PROD_PROJECT"
step "Publishing status must say In production. If it says Testing, click Publish app, then Confirm."
note "Google mentions verification because calendar.events is sensitive; the app still goes In production."
note "In Testing, Members' calendar access would end after seven days."
pause "Press Enter when it says In production."
step "Find the user cap line (it reads like 12 users / 100). Type what it shows, or none if there isn't one."
ask USER_CAP "User cap:"
NOTES+=("Production user cap: $USER_CAP")

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Production: save the settings in AWS"
save_settings prod "$PROD_CLIENT_ID" "$PROD_CLIENT_SECRET"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Try it on dev"
say "Do this once Claude says Add to Google Calendar is on dev. If it isn't yet, press Enter and come back later."
open_url "https://dev.craigdevjohnson.com/soccer"
step "Sign in, add one of your Teams, choose Google Calendar, then Add to Google Calendar."
step "Click Connect Google Calendar, pick your account and allow access. Google may warn the app isn't verified: continue."
step "Back on the page, pick a calendar and click Add N games. Check the games appear in Google Calendar."
pause "Press Enter when you've tried it, or to finish for now."

finish
for n in "${NOTES[@]}"; do note "$n"; done
note "Send Claude the two lines above, and whether adding games on dev worked."
printf '\n'
